export const CATALOG = new Map(entries.map((entry) => [entry.id, entry]));
const SAMPLE_CATALOG = new Map();
for (const entry of entries) {
  entry.sampleIds.forEach((sampleId, index) => SAMPLE_CATALOG.set(sampleId, {
    modelId: entry.id, dataset: entry.dataset, sourceId: entry.sourceIds[index],
  }));
}

export function getCatalogEntry(modelId) {
  return typeof modelId === 'string' ? CATALOG.get(modelId) ?? null : null;
}

export function getCatalogSample(sampleId) {
  return typeof sampleId === 'string' ? SAMPLE_CATALOG.get(sampleId) ?? null : null;
}

export function isCatalogSample(modelId, sampleId) {
  return getCatalogSample(sampleId)?.modelId === modelId;
}
